   {
      this.thingName.text = _global.gradeName[this.grade] + this.name;
   }
   else if(this.type == "幸运符")
   {
      this.thingName.text = _global.gradeName[this.grade] + this.type;
   }
   else if(this.type == "戒指")
   {
      this.thingName.text = this.name;
   }
   else if(this.type == "庇护铃铛" || this.type == "翡翠铃铛" || this.type == "凤翼铃铛")
   {
      this.thingName.text = _global.gradeName[this.grade] + this.type;
   }
   else if(this.type == "技能书" || this.type == "药品")
   {
